{
  "category_edits": [
    {
      "category": "interaction_mechanism",
      "rationale": "Learn one diagonal compatibility vector initialized to ones within each category's SASRec model. This lets training adjust each interest/item coordinate's contribution while preserving the Transformer, input features, history readout, loss, optimizer, and training settings. Training and prediction use the same checkpointed scorer.",
      "edits": [
        {
          "find": "        self.last_layernorm = nn.LayerNorm(hidden_units, eps=1e-8)\n",
          "replace": "        self.last_layernorm = nn.LayerNorm(hidden_units, eps=1e-8)\n        self.interaction_diag = nn.Parameter(torch.ones(hidden_units))\n"
        },
        {
          "find": "        pos_logits = (log_feats * pos_embs).sum(dim=-1)\n        neg_logits = (log_feats * neg_embs).sum(dim=-1)",
          "replace": "        interaction_feats = log_feats * self.interaction_diag\n        pos_logits = (interaction_feats * pos_embs).sum(dim=-1)\n        neg_logits = (interaction_feats * neg_embs).sum(dim=-1)"
        },
        {
          "find": "        final_feat = log_feats[:, -1, :]\n        item_embs = self.item_emb(candidates)",
          "replace": "        final_feat = log_feats[:, -1, :] * self.interaction_diag\n        item_embs = self.item_emb(candidates)"
        },
        {
          "find": "            \"interest_aggregation\": \"causal_recency_half_life_5_blend_0.2_v1\",\n            \"hidden_units\": HIDDEN_UNITS,",
          "replace": "            \"interest_aggregation\": \"causal_recency_half_life_5_blend_0.2_v1\",\n            \"interaction_mechanism\": \"learned_diagonal_compatibility_v1\",\n            \"hidden_units\": HIDDEN_UNITS,"
        },
        {
          "find": "        # The imported SASRec applies the same causal recency readout as training.\n        _metas[ds] = meta",
          "replace": "        if meta.get(\"interaction_mechanism\") != \"learned_diagonal_compatibility_v1\":\n            raise ValueError(f\"Unexpected interaction mechanism configuration for {ds}\")\n        # The imported SASRec includes the checkpointed diagonal compatibility scorer.\n        _metas[ds] = meta"
        }
      ]
    }
  ],
  "change_summary": "Replace dot-product scoring with jointly learned diagonal compatibility across all four category models. The predictor imports the updated SASRec and strictly loads its learned diagonal from each category's single checkpoint. Epoch cap and all other settings remain unchanged."
}
